using System;using System.Linq;using System.Collections.Generic;
namespace IdleIntelligence.Core {
 [Serializable]public sealed class PinnedGoal {public string kind,id;public bool hasTarget;public long target;public PinnedGoal Copy()=>(PinnedGoal)MemberwiseClone();}
 [Serializable]public sealed class GuidanceState {public int schema=1;public bool initialized=true,hasPinned;public PinnedGoal pinned;public GuidanceState Copy()=>new GuidanceState{schema=schema,initialized=initialized,hasPinned=hasPinned,pinned=hasPinned?pinned?.Copy():null};}
 public sealed class GoalQuote {public string Kind,Id,Title,Progress,Missing="",Benefit="",Tab,Element,Mode="";public bool Reached,HasCost,LegacyResearchQuote;public long Target;public double Eta=-1;public ScientificNumber Cost=ScientificNumber.Zero,MissingAmount=ScientificNumber.Zero,ActualCost=ScientificNumber.Zero;}
 public sealed class ReturnAction {public string Kind,Id="",Tab,Element="",Mode="";}
 public static class GuidanceRules {
  public static readonly string[] Kinds={"hardware","research","recipe","prestige","item-craft","item-upgrade","blueprint-mastery"};
  static string Name(GameState s,string prefix,string id)=>SettingsRules.Text(s.Settings.language,prefix+":"+id);
  static double Eta(ScientificNumber balance,ScientificNumber cost,ScientificNumber rate){var missing=cost.Subtract(balance);if(missing.IsZero)return 0;if(rate.IsZero)return -1;var seconds=missing.Divide(rate);return seconds.CompareTo(ScientificNumber.From(9007199254740991d))<=0?seconds.ToDouble():-1;}
  static GoalQuote Costed(GoalQuote q,ScientificNumber balance,ScientificNumber cost,ScientificNumber rate){q.HasCost=true;q.Cost=cost;q.MissingAmount=cost.Subtract(balance);q.Eta=Eta(balance,cost,rate);return q;}
  public static GameState Pin(GameState state,PinnedGoal pin){if(pin!=null&&!Kinds.Contains(pin.kind))return state;if(pin!=null&&Resolve(state,pin)==null)return state;var n=state.Copy();n.Guidance.hasPinned=pin!=null;n.Guidance.pinned=pin?.Copy();LocalJournal.Record(n,"goal-selected",pin==null?"":pin.kind+":"+pin.id+(pin.hasTarget?":"+pin.target:""));return n;}
  public static GoalQuote Resolve(GameState s,PinnedGoal pin){if(pin==null)return null;string kind=pin.kind,id=pin.id;var q=new GoalQuote{Kind=kind,Id=id};
   if(kind=="hardware"){int i=Array.FindIndex(Balance.Hardware,h=>h.Id==id);if(i<0)return null;long target=pin.hasTarget?pin.target:Balance.Hardware[i].Milestones.FirstOrDefault(m=>m.Threshold>s.Hardware[i])?.Threshold??s.Hardware[i];q.Target=target;q.Reached=s.Hardware[i]>=target;q.Title=Name(s,"hardware",id)+" · "+target;q.Progress=Math.Min(s.Hardware[i],target)+" / "+target;q.Tab="hardware";q.Element="hardware-"+id;q.Benefit="Hardware milestone";Costed(q,s.Credits,q.Reached?ScientificNumber.Zero:Game.HardwareCost(s,i,target-s.Hardware[i]),Game.Income(s));if(q.Reached)q.Eta=-1;return q;}
   if(kind=="research"){int i=Game.ResearchIndex(id);if(i<0)return null;var d=Balance.Research[i];long target=d.Project?1:pin.hasTarget?pin.target:s.Research[i]+1L;q.Target=target;q.Reached=s.Research[i]>=target;q.Title=Name(s,"research",id)+" · Lv. "+target;q.Progress=s.Research[i]+" / "+target;q.Tab="research";q.Element="research-"+id;q.Benefit=Name(s,d.Project?"project-effect":"research-effect",id);var cost=d.Project?ScientificNumber.FromData(NavigationCatalog.LegacyProjectCosts[i]):Game.Ceil(ScientificNumber.From(NavigationCatalog.LegacyResearchBase[i]).Multiply(ScientificNumber.From(NavigationCatalog.LegacyResearchGrowth).Pow(Math.Max(0,target-1))));q.ActualCost=Game.ResearchCost(s,i);q.LegacyResearchQuote=cost.CompareTo(q.ActualCost)!=0;var blocked=d.Requires.Any(r=>Game.Level(s,r.Id)<r.Level);Costed(q,s.Data,cost,Game.DataRate(s));if(blocked)q.Eta=-1;q.Missing=q.Reached?"Reached":blocked?"Missing research prerequisite":q.MissingAmount+" Data missing";return q;}
   if(kind=="prestige"){string mapped=NavigationCatalog.LegacyNodes.TryGetValue(id,out var alias)?alias:id;var node=PrestigeBalance.Nodes.FirstOrDefault(n=>n.Id==mapped);if(node==null)return null;q.Reached=PrestigeRules.Has(s,mapped);q.Title=Name(s,"node",mapped);q.Progress=s.Prestige.Free+" / "+node.Cost+" INT";q.Tab="prestige";q.Element="";q.Benefit=Name(s,"node-effect",mapped);q.HasCost=true;q.Cost=ScientificNumber.From(node.Cost);q.MissingAmount=q.Cost.Subtract(s.Prestige.Free);return q;}
   if(kind=="item-upgrade"){var item=s.Workshop.inventory.FirstOrDefault(i=>i.id==id);if(item==null)return null;var quote=Workshop.UpgradeQuote(s,item);q.Target=pin.hasTarget?pin.target:item.level+1L;q.Reached=item.level>=q.Target;q.Title=Name(s,"item",item.type)+" · upgrade";q.Progress=item.level+" / "+q.Target;q.Missing=q.Reached?"":quote.Reason??"";q.Tab="items";q.Mode="inventory";q.Element="item-"+id;Costed(q,s.Data,ScientificNumber.From(quote.Data),Game.DataRate(s));q.Eta=-1;return q;}
   int index=Workshop.Index(id);if(index<0)return null;q.Title=Name(s,"item",id);q.Tab="items";q.Mode="blueprints";q.Element="recipe-"+id;var craft=Workshop.Quote(s,id);
   if(kind=="recipe"){q.Reached=craft.Allowed;q.Progress=q.Reached?"Ready":craft.Reason??"";q.Missing=q.Progress;return q;}
   if(kind=="item-craft"){q.Target=pin.hasTarget?pin.target:s.Workshop.crafted[index]+1L;q.Reached=s.Workshop.crafted[index]>=q.Target;q.Progress=Math.Min(s.Workshop.crafted[index],q.Target)+" / "+q.Target;q.Missing=q.Reached?"":craft.Reason??"";return q;}
   if(kind=="blueprint-mastery"){int level=s.Workshop.mastery[index];q.Target=pin.hasTarget?pin.target:Math.Min(4,level+1);q.Reached=level>=q.Target;q.Progress=level+" / "+q.Target;q.Missing=q.Reached?"":!Workshop.Prerequisite(s,index)||!s.Workshop.learned[index]?"Recipe access / blueprint required":s.Workshop.crafted[index]<1?"First craft an instance regularly":Math.Max(0,ItemBalance.MasteryCosts[Math.Min(3,level)]-s.Workshop.fragments)+" blueprint fragments missing";return q;}return null;
  }
  static bool Rewards(GameState s){if(ChallengeRules.Active(s))return false;foreach(var p in new[]{s.Missions.daily,s.Missions.weekly,s.Missions.monthly})if(p.tasks.Any(t=>!t.claimed&&MissionRules.Complete(s,t))||p.required>0&&!p.bonusClaimed&&p.tasks.Count(t=>MissionRules.Complete(s,t))>=p.required)return true;foreach(var p in new[]{s.Missions.season,s.Missions.hasPrevious?s.Missions.previous:null}.Where(p=>p!=null))if(Enumerable.Range(1,SeasonRules.Level(p)).Any(level=>!p.claimed.Contains(level)||SeasonRules.Premium(s,p.id)&&!p.premiumClaimed.Contains(level)))return true;return false;}
  public static GoalQuote Next(GameState s){if(s.Story.tutorial=="active"){var guide=TutorialNavigation.Quote(s);return new GoalQuote{Kind="tutorial",Id=s.Story.target??"",Title=guide?.Title??"Mira",Progress=guide?.Explanation??"Continue dialogue",Tab=guide?.Tab??"story",Element=guide?.Element??"",Mode=guide?.Mode??""};}if(s.Retention.onboardingCompleted.Except(s.Retention.onboardingClaimed).Any())return new GoalQuote{Kind="tutorial",Id="onboarding",Title="Claim reward",Progress="Lab goals",Tab="profile",Element=""};if(Rewards(s))return new GoalQuote{Kind="reward",Title="Claim reward",Progress="A quest or Season reward is ready.",Tab="missions",Element=""};if(s.Guidance.hasPinned){var pinned=Resolve(s,s.Guidance.pinned);if(pinned!=null)return pinned;}int next=Array.FindIndex(s.Hardware,n=>n==0);if(next>=0){var q=Resolve(s,new PinnedGoal{kind="hardware",id=Balance.Hardware[next].Id,hasTarget=true,target=1});q.Reached=false;return q;}return new GoalQuote{Kind="complete",Title="All hardware classes discovered",Progress="Prestige: "+PrestigeRules.Claim(s)+" INT",Tab="prestige",Element=""};}
  public static PinnedGoal[] Candidates(GameState s){var list=new List<PinnedGoal>();foreach(var h in Balance.Hardware){int i=Array.IndexOf(Balance.Hardware,h);var m=h.Milestones.FirstOrDefault(x=>x.Threshold>s.Hardware[i]);if(m!=null)list.Add(new PinnedGoal{kind="hardware",id=h.Id,hasTarget=true,target=m.Threshold});}list.AddRange(NavigationCatalog.ResearchOrder.Select(id=>new PinnedGoal{kind="research",id=id}));foreach(string kind in new[]{"recipe","item-craft","blueprint-mastery"})foreach(var itemId in NavigationCatalog.RecipeOrder){int i=Workshop.Index(itemId);if(kind=="blueprint-mastery"&&s.Workshop.mastery[i]>=4)continue;list.Add(new PinnedGoal{kind=kind,id=itemId,hasTarget=kind!="recipe",target=kind=="item-craft"?s.Workshop.crafted[i]+1L:s.Workshop.mastery[i]+1L});}list.AddRange(s.Workshop.inventory.Where(i=>i.level<ItemBalance.MaxLevel).Select(i=>new PinnedGoal{kind="item-upgrade",id=i.id,hasTarget=true,target=i.level+1}));list.AddRange(NavigationCatalog.PrestigeGoalIds.Where(id=>!s.Workshop.nodes.Contains(id)).Take(5).Select(id=>new PinnedGoal{kind="prestige",id=id}));return list.ToArray();}
  public static ReturnAction[] Return(GameState s){if(ChallengeRules.Active(s)||s.Challenges.Main!=null)return Array.Empty<ReturnAction>();var list=new List<ReturnAction>();if(s.Missions.boxes.pending.Length>0)list.Add(new ReturnAction{Kind="boxes",Tab="missions"});if(s.Workshop.inventory.Any(i=>{string slot=Workshop.EquipmentSlot(s,i.id);return slot!=null&&string.IsNullOrEmpty(s.Workshop.equipped[Array.IndexOf(ItemBalance.Slots,slot)]);}))list.Add(new ReturnAction{Kind="equipment",Tab="items",Mode="inventory"});if(PrestigeRules.Has(s,"T03")&&s.Prestige.trainingQueue.Length==0)list.Add(new ReturnAction{Kind="queue",Tab="training"});else if(s.Training==null&&s.Prestige.trainingQueue.Length==0&&new[]{"quality","efficiency"}.Any(track=>Game.TrainingAvailable(s,track)&&s.Credits.CompareTo(Game.TrainingCost(s,track))>=0&&s.Data.CompareTo(Game.TrainingData(s,track))>=0))list.Add(new ReturnAction{Kind="training",Tab="training"});string research=NavigationCatalog.ResearchOrder.FirstOrDefault(id=>Game.ResearchBlock(s,Game.ResearchIndex(id))==null);if(research!=null)list.Add(new ReturnAction{Kind="research",Id=research,Tab="research",Element="research-"+research});return list.Take(2).ToArray();}
  public static GameState OnAdvance(GameState before,GameState after){if(!before.Guidance.hasPinned||!after.Guidance.hasPinned)return after;var b=Resolve(before,before.Guidance.pinned);var a=Resolve(after,after.Guidance.pinned);if(b!=null&&a!=null&&!b.Reached&&a.Reached)LocalJournal.Record(after,"goal-completed",after.Guidance.pinned.id);return after;}
  public static void Validate(GuidanceState g){if(g==null||!g.initialized||g.schema!=1||g.hasPinned&&(g.pinned==null||!Kinds.Contains(g.pinned.kind)||string.IsNullOrEmpty(g.pinned.id)||g.pinned.id.Length>200||g.pinned.target<0||g.pinned.target>9007199254740991L))throw new FormatException("Invalid pinned goal");}
 }
}
